import{_ as i,c as e,o as l,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"隱私權政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1787284674000}'),t={name:"zh-TW/guide/privacy.md"};function o(n,a,s,h,c,p){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><p>ClipboxAI 是一款專為 macOS 打造的智慧剪貼簿管理工具。你的隱私是我們的首要考量。</p><h2 id="本機優先設計" tabindex="-1">本機優先設計 <a class="header-anchor" href="#本機優先設計" aria-label="Permalink to &quot;本機優先設計&quot;">​</a></h2><ul><li>你的剪貼簿歷史完全儲存在你的 Mac 上。</li><li>內建本地動作（擷取連結、統計計數、摺疊空白行，以及裝置端 ML 建議）完全離線執行。</li><li>使用核心應用程式不需要任何帳號或註冊。</li><li>本地剪貼簿管理與裝置端功能不需要任何網際網路連線。</li></ul><h2 id="雲端-ai-選用" tabindex="-1">雲端 AI（選用） <a class="header-anchor" href="#雲端-ai-選用" aria-label="Permalink to &quot;雲端 AI（選用）&quot;">​</a></h2><p>ClipboxAI 可以選擇性地使用雲端 AI 供應商（例如 DeepSeek、MiniMax、GLM、Kimi、Mistral，或本地的 Ollama 伺服器），來驅動摘要、翻譯與自訂提示等進階動作。</p><ul><li>啟用後，所選文字或剪貼內容會使用<strong>你自己的 API key</strong>，<strong>直接傳送給你所設定的供應商</strong>。</li><li>你的 API key 僅儲存在你 Mac 的 Keychain 中，絕不會上傳給我們。</li><li>你可以隨時停用雲端 AI，繼續使用本地功能。</li><li>剪貼簿歷史<strong>不會</strong>自動傳送到雲端；雲端請求只有在你執行雲端動作時才會觸發。</li></ul><h2 id="我們不會蒐集的項目" tabindex="-1">我們不會蒐集的項目 <a class="header-anchor" href="#我們不會蒐集的項目" aria-label="Permalink to &quot;我們不會蒐集的項目&quot;">​</a></h2><ul><li>我們不會蒐集你的剪貼簿內容、文件或檔案。</li><li>我們不會追蹤你的活動、瀏覽行為或使用模式。</li><li>我們不會營運任何接收你剪貼簿資料的伺服器。</li><li>我們不包含任何第三方的分析、廣告或追蹤 SDK。</li><li>我們沒有任何遙測系統。</li></ul><h2 id="儲存在本地的資料" tabindex="-1">儲存在本地的資料 <a class="header-anchor" href="#儲存在本地的資料" aria-label="Permalink to &quot;儲存在本地的資料&quot;">​</a></h2><p>以下資料僅儲存在你的裝置上：</p><ul><li><strong>剪貼簿歷史</strong>：供快速存取的最近項目（保留在你的 Mac 上）。</li><li><strong>應用程式設定</strong>：主題、語言偏好、已啟用的動作、供應商設定。</li><li><strong>API key</strong>：安全地儲存在本地 Keychain 中（僅在你設定雲端供應商時）。</li><li><strong>自訂動作</strong>：你建立的提示與設定。</li><li><strong>日誌</strong>：供疑難排解的除錯日誌（可隨時刪除）。</li></ul><h2 id="應用程式使用的權限" tabindex="-1">應用程式使用的權限 <a class="header-anchor" href="#應用程式使用的權限" aria-label="Permalink to &quot;應用程式使用的權限&quot;">​</a></h2><ul><li><strong>輔助使用／完全磁碟存取</strong>：讀取系統剪貼簿並提供全域快捷鍵所需。</li><li><strong>通知</strong>：選用，用於長時間雲端請求完成時的提醒。</li></ul><p>你可以隨時在 <strong>System Settings → Privacy &amp; Security（系統設定 → 隱私權與安全性）</strong> 中管理這些權限。</p><h2 id="應用程式內購買-授權" tabindex="-1">應用程式內購買／授權 <a class="header-anchor" href="#應用程式內購買-授權" aria-label="Permalink to &quot;應用程式內購買／授權&quot;">​</a></h2><p>授權購買（若有）由 Apple 透過 Mac App Store 處理。ClipboxAI 不會接收或儲存你的付款資訊。授權收據會儲存在本地以驗證所有權。</p><h2 id="第三方服務" tabindex="-1">第三方服務 <a class="header-anchor" href="#第三方服務" aria-label="Permalink to &quot;第三方服務&quot;">​</a></h2><p>ClipboxAI 本身不包含任何第三方的分析、廣告或追蹤服務。當你啟用某個雲端 AI 供應商時，你的請求會由該供應商依其自身的隱私權政策處理。</p><h2 id="隱私權請求" tabindex="-1">隱私權請求 <a class="header-anchor" href="#隱私權請求" aria-label="Permalink to &quot;隱私權請求&quot;">​</a></h2><p>由於 ClipboxAI 將所有資料儲存在你裝置的本地上，我們的伺服器上並未持有任何個人資料。若你對隱私有任何疑問，請與我們聯繫。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>若有隱私權相關問題，請在 <a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 開啟一個 issue，或透過電子郵件 <a href="mailto:clipboxai@w3cub.com" target="_blank" rel="noreferrer">clipboxai@w3cub.com</a> 與我們聯繫。</p>',23)])])}const b=i(t,[["render",o]]);export{u as __pageData,b as default};
